from collections import deque
from fractions import Fraction

def bfs(u_max, v_max, target, blocks):
    blocked_set = set(blocks)
    start = (0, 0)
    if start in blocked_set or target in blocked_set:
        return None
    dq = deque([(start, 0)])
    seen = {start}
    while dq:
        (x, y), d = dq.popleft()
        if (x, y) == target:
            return d
        for dx, dy in [(1,0), (-1,0), (0,1), (0,-1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx <= u_max and 0 <= ny <= v_max and (nx, ny) not in blocked_set:
                if (nx, ny) not in seen:
                    seen.add((nx, ny))
                    dq.append(((nx, ny), d + 1))
    return None

def dp_prob(p_e, p_w, p_n, p_s, u_max, v_max, target, t_steps, blocks):
    blocked_set = set(blocks)
    # absorb upon entering target; do not propagate from target
    dist = {(0, 0): Fraction(1, 1)}
    absorbed = Fraction(0, 1)
    for _ in range(t_steps):
        new = {}
        for (x, y), mass in dist.items():
            # Attempt moves
            # Right
            nx, ny = x + 1, y
            if 0 <= nx <= u_max and 0 <= ny <= v_max and (nx, ny) not in blocked_set:
                w = mass * p_e
                if (nx, ny) == target:
                    absorbed += w
                else:
                    new[(nx, ny)] = new.get((nx, ny), Fraction(0, 1)) + w
            # Left
            nx, ny = x - 1, y
            if 0 <= nx <= u_max and 0 <= ny <= v_max and (nx, ny) not in blocked_set:
                w = mass * p_w
                if (nx, ny) == target:
                    absorbed += w
                else:
                    new[(nx, ny)] = new.get((nx, ny), Fraction(0, 1)) + w
            # Up
            nx, ny = x, y + 1
            if 0 <= nx <= u_max and 0 <= ny <= v_max and (nx, ny) not in blocked_set:
                w = mass * p_n
                if (nx, ny) == target:
                    absorbed += w
                else:
                    new[(nx, ny)] = new.get((nx, ny), Fraction(0, 1)) + w
            # Down
            nx, ny = x, y - 1
            if 0 <= nx <= u_max and 0 <= ny <= v_max and (nx, ny) not in blocked_set:
                w = mass * p_s
                if (nx, ny) == target:
                    absorbed += w
                else:
                    new[(nx, ny)] = new.get((nx, ny), Fraction(0, 1)) + w
        dist = new
    return absorbed

# Try until a non-trivial instance is found
